                        '```javascript',
                        '// Struktur proyek pbo-lab\n// pbo-lab/\n// ├── src/\n// │   ├── model/       # Kelas domain\n// │   ├── service/     # Logika bisnis\n// │   ├── repository/  # Persistensi\n// │   ├── view/        # Antarmuka\n// │   └── index.js     # Entry point\n// ├── test/            # Unit test\n// ├── docs/            # Dokumentasi\n// ├── package.json\n// └── README.md\n\nconst STRUKTUR = {\n    model: [\'Mahasiswa\', \'MataKuliah\', \'Nilai\'],\n    service: [\'MahasiswaService\', \'NilaiService\'],\n    repository: [\'MahasiswaRepository\', \'NilaiRepository\'],\n    view: [\'MahasiswaView\', \'DashboardView\'],\n    test: [\'mahasiswa.test.js\', \'nilai.test.js\']\n};\n\nconsole.log(\'Struktur pbo-lab siap dibangun\');',
                        '```',
                        '---',
                        '### Studi Kasus: Sistem Akademik',
                        'Sistem akademik adalah studi kasus yang kaya: mahasiswa, mata kuliah, nilai, dan transkrip. Setiap entitas adalah kelas dengan tanggung jawab yang jelas.',
                        '```javascript',
                        '// Studi kasus: sistem akademik\nclass Mahasiswa {\n    #nilai = new Map();\n    constructor(nama, nim) {\n        this.nama = nama;\n        this.nim = nim;\n    }\n    tambahNilai(kodeMK, nilai) {\n        if (nilai < 0 || nilai > 100) {\n            throw new Error(\'Nilai harus antara 0 dan 100\');\n        }\n        this.#nilai.set(kodeMK, nilai);\n    }\n    ipk() {\n        if (this.#nilai.size === 0) return 0;\n        const total = Array.from(this.#nilai.values()).reduce((a, b) => a + b, 0);\n        return total / this.#nilai.size / 25; // Konversi ke skala 4\n    }\n    transkrip() {\n        return Array.from(this.#nilai.entries()).map(([mk, n]) => ({ mk, n }));\n    }\n}\n\nclass MataKuliah {\n    constructor(kode, nama, sks) {\n        this.kode = kode;\n        this.nama = nama;\n        this.sks = sks;\n    }\n}\n\nconst mhs = new Mahasiswa(\'Andi\', \'2023001\');\nmhs.tambahNilai(\'PBO\', 85);\nmhs.tambahNilai(\'CV\', 90);\nconsole.log(\'IPK:\', mhs.ipk().toFixed(2));\nconsole.log(\'Transkrip:\', mhs.transkrip());',
                        '```',
