                        '```javascript',
                        '// Fitur kunci pbo-lab\nconst FITUR_PBO_LAB = {\n    model: [\'Mahasiswa\', \'MataKuliah\', \'Nilai\', \'Transkrip\'],\n    enkapsulasi: [\'private field\', \'getter dan setter\', \'validasi\'],\n    pewarisan: [\'abstract class\', \'interface\', \'polimorfisme\'],\n    koleksi: [\'Array\', \'Map\', \'Set\'],\n    io: [\'baca file\', \'tulis file\', \'serialisasi JSON\'],\n    pola: [\'Singleton\', \'Factory\', \'Observer\', \'Repository\'],\n    gui: [\'formulir\', \'event handling\', \'MVC\'],\n    pengujian: [\'unit test\', \'assert\', \'cakupan\']\n};\n\nconsole.log(\'Fitur yang harus didemokan:\', Object.keys(FITUR_PBO_LAB));',
